function normalizeMission(card) {
  const normalized = {
    id: card.id,
    text: card.text,
    kind: 'mission',
    r18: false,
    touch: 0,
    difficulty: card.difficulty,
    category: card.category,
    target: card.target,
    topic: card.topic,
    scenes: [...card.scenes],
    minPlayers: Number.isInteger(card.minPlayers) ? card.minPlayers : 3,
  };
  if (card.target === 'seat' && card.seat) normalized.seat = card.seat;
  if (card.revealNote) normalized.revealNote = card.revealNote;
  if (card.retired === true) normalized.retired = true;
  return Object.freeze(normalized);
}

// 正規化して公開する
export const missionCards = Object.freeze(missionCardDefs.map(normalizeMission));

export default missionCards;
